import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void conv1d_kernel(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_length,
    int kernel_size,
    int stride,
    int dilation,
    int output_length
) {
    int batch_idx = blockIdx.x;
    int out_ch_idx = blockIdx.y;
    int out_pos_idx = blockIdx.z * blockDim.x + threadIdx.x;

    if (batch_idx >= batch_size || out_ch_idx >= out_channels || out_pos_idx >= output_length) {
        return;
    }

    // Shared memory for input window
    extern __shared__ half shared_input[];

    // Initialize accumulator
    float acc = 0.0f;

    // Loop over input channels and kernel positions
    for (int ch = 0; ch < in_channels; ++ch) {
        // Load input data into shared memory
        int input_base = batch_idx * in_channels * input_length + ch * input_length;
        int output_base = batch_idx * out_channels * output_length + out_ch_idx * output_length;
        int weight_base = out_ch_idx * in_channels * kernel_size + ch * kernel_size;

        // For each kernel position
        for (int k = 0; k < kernel_size; ++k) {
            int input_pos = out_pos_idx * stride + k * dilation;

            // Bounds checking
            if (input_pos >= 0 && input_pos < input_length) {
                half input_val = input[input_base + input_pos];
                half weight_val = weight[weight_base + k];

                // Accumulate with float precision
                acc += __half2float(input_val) * __half2float(weight_val);
            }
        }
    }

    // Write result
    if (out_pos_idx < output_length) {
        output[output_base + out_pos_idx] = __float2half(acc);
    }
}

// Wrapper function to launch kernel
extern "C" void launch_conv1d(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_length,
    int kernel_size,
    int stride,
    int dilation,
    int output_length
) {
    dim3 grid(batch_size, out_channels, (output_length + 255) / 256);
    dim3 block(256);
    size_t shared_mem_size = in_channels * input_length * sizeof(half);

    conv1d_kernel<<<grid, block, shared_mem_size>>>(
        input, weight, output,
        batch_size, in_channels, out_channels,
        input_length, kernel_size, stride, dilation, output_length
    );
}
"""

# Python wrapper
def launch_conv1d_cuda(input_tensor, weight_tensor, bias=None, stride=1, dilation=1):
    batch_size, in_channels, input_length = input_tensor.shape
    out_channels, _, kernel_size = weight_tensor.shape

    # Calculate output length
    output_length = (input_length + 2 * 0 - (dilation * (kernel_size - 1) + 1)) // stride + 1

    # Create output tensor
    output = torch.empty(batch_size, out_channels, output_length, dtype=torch.float16, device=input_tensor.device)

    # Launch kernel
    launch_conv1d = load_inline(
        name="conv1d_cuda",
        cpp_sources=cuda_source,
        functions=["launch_conv1d"],
        verbose=False
    )

    launch_conv1d.launch_conv1d(
        input_tensor.data_ptr(),
        weight_tensor.data_ptr(),
        output.data_ptr(),
        batch_size,
        in_channels,
        out_channels,
        input_length,
        kernel_size,
        stride,
        dilation,
        output_length
    )

    return output

class ModelNew(torch.nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
