        if bias:
            self.bias = torch.nn.Parameter(torch.randn(out_channels, dtype=torch.float16))
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Use custom CUDA kernel
        output = launch_conv1d_cuda(
            x, 
            self.weight, 
            self.bias,
            stride=self.stride,
            dilation=self.dilation
        )
